#!/usr/bin/env python3
"""
Generate PILean's golden test fixtures under `testdata/golden/` using Pillow
11.3.0 as the correctness oracle, plus the PngSuite pixel-truth corpus
under `testdata/corpus/pngsuite-truth/`.

Everything here is deterministic: every random draw goes through a
`random.Random(seed)` seeded from the table in `PATTERN_SEEDS` /
`ZLIB_SEEDS` below (also echoed into `testdata/golden/MANIFEST.md`). Re-running
this script must reproduce byte-identical output.

Usage:
    python3 testdata/py/gen_golden.py

Regenerates every file under `testdata/golden/` and refreshes
`testdata/corpus/pngsuite-truth/` (skipped with a warning if the corpus isn't
vendored). Nothing here touches `testdata/golden/netpbm/` or
`testdata/golden/bmp/` as directories — those are owned by other work
packages; this script's own BMP/PPM/PGM outputs live flat under
`testdata/golden/` instead (see MANIFEST.md).
"""
from __future__ import annotations

import io
import random
import sys
import zlib
from pathlib import Path

from PIL import Image

sys.path.insert(0, str(Path(__file__).resolve().parent))
import praw  # noqa: E402
import pngsuite_truth  # noqa: E402

ROOT = Path(__file__).resolve().parent.parent  # testdata/
GOLDEN = ROOT / "golden"
ZLIB_DIR = GOLDEN / "zlib"

# ---------------------------------------------------------------------------
# Seeds (recorded here AND in MANIFEST.md — the two must be kept in sync;
# MANIFEST.md is regenerated by this script's final step from this table).
# ---------------------------------------------------------------------------

PATTERN_SEEDS = {
    "hgradient": 1001,
    "vgradient": 1002,
    "checker8": 1003,
    "noise": 1004,
    "flat": 1005,
    "fewcolors": 1006,
}
PHOTO_SEED = 1007
ANIM_SEED = 1008

ZLIB_SEEDS = {
    "one": 2001,
    "random4k": 2002,
    "b65535": 2003,
    "b65536": 2004,
    "random100k": 2005,
}

SIZES = [(16, 16), (33, 17)]
TINY_SIZE = (1, 1)
MODES = ["l", "la", "rgb", "rgba", "p"]

# Pixel values printed at the end for hardcoding into
# Tests/RoundTripTests.lean (per the work package spec).
PRINTED_PIXELS_OF = "hgradient_rgb_16x16"
PRINTED_COORDS = [(0, 0), (15, 0), (0, 15), (15, 15), (7, 3)]


# ---------------------------------------------------------------------------
# Pattern generation: every pattern reduces to a small RGB palette plus a
# per-pixel index grid. This keeps P-mode generation exact (no Pillow
# quantization involved) and lets every other mode derive its pixel values
# directly from the same palette, so every mode variant of one pattern
# depicts the *same* image.
# ---------------------------------------------------------------------------

def gen_flat(rng: random.Random, w: int, h: int):
    color = (rng.randrange(256), rng.randrange(256), rng.randrange(256))
    idx = [[0] * w for _ in range(h)]
    return [color], idx


def gen_checker8(rng: random.Random, w: int, h: int):
    c0 = (rng.randrange(256), rng.randrange(256), rng.randrange(256))
    c1 = (rng.randrange(256), rng.randrange(256), rng.randrange(256))
    idx = [[((x // 8) + (y // 8)) % 2 for x in range(w)] for y in range(h)]
    return [c0, c1], idx


def _tint_ramp(n: int) -> list[tuple[int, int, int]]:
    """`n` deterministically-tinted (non-grayscale) ramp colors, `n<=256`.
    Never the literal identity ramp `(i,i,i)` — GIF's `_is_palette_needed`
    would then omit the color table and Pillow would reopen it as mode `L`
    instead of `P`, which would break the P-mode round-trip fixtures."""
    out = []
    for i in range(n):
        v = 255 if n <= 1 else round(i * 255 / (n - 1))
        out.append((v, (v + 85) % 256, (v + 170) % 256))
    return out


def gen_hgradient(rng: random.Random, w: int, h: int):
    del rng  # purely positional; no randomness needed
    palette = _tint_ramp(w)
    idx = [[x for x in range(w)] for _ in range(h)]
    return palette, idx


def gen_vgradient(rng: random.Random, w: int, h: int):
    del rng
    palette = _tint_ramp(h)
    idx = [[y for _ in range(w)] for y in range(h)]
    return palette, idx


def gen_noise(rng: random.Random, w: int, h: int):
    k = min(256, w * h)
    palette = [(rng.randrange(256), rng.randrange(256), rng.randrange(256)) for _ in range(k)]
    idx = [[rng.randrange(k) for _ in range(w)] for _ in range(h)]
    return palette, idx


def gen_fewcolors(rng: random.Random, w: int, h: int):
    k = min(16, max(2, 3 + rng.randrange(13)))
    palette = [(rng.randrange(256), rng.randrange(256), rng.randrange(256)) for _ in range(k)]
    idx = [[(x * 7 + y * 13) % k for x in range(w)] for y in range(h)]
    return palette, idx


PATTERNS = {
    "hgradient": gen_hgradient,
    "vgradient": gen_vgradient,
    "checker8": gen_checker8,
    "noise": gen_noise,
    "flat": gen_flat,
    "fewcolors": gen_fewcolors,
}


def luma(r: int, g: int, b: int) -> int:
    """ITU-R 601-2 luma, matching `PILean.Color.luma`'s rounded fixed-point
    formula — used only to pick our own ground-truth `L`/`LA` pixel values,
    not because Pillow needs it (we build `L`/`LA` images directly)."""
    return (r * 19595 + g * 38470 + b * 7471 + 0x8000) >> 16


def alpha_at(x: int, y: int, pattern: str) -> int:
    """Deterministic per-pixel alpha for `LA`/`RGBA` variants: constant
    (opaque) for `flat` so at least one fixture has no alpha variation,
    a smooth function of position otherwise."""
    if pattern == "flat":
        return 255
    return (x * 31 + y * 17 + 7) % 256


def build_mode_bytes(mode: str, palette, idx, w: int, h: int, pattern: str) -> bytes:
    out = bytearray()
    if mode == "l":
        for y in range(h):
            for x in range(w):
                r, g, b = palette[idx[y][x]]
                out.append(luma(r, g, b))
    elif mode == "la":
        for y in range(h):
            for x in range(w):
                r, g, b = palette[idx[y][x]]
                out.append(luma(r, g, b))
                out.append(alpha_at(x, y, pattern))
    elif mode == "rgb":
        for y in range(h):
            for x in range(w):
                out += bytes(palette[idx[y][x]])
    elif mode == "rgba":
        for y in range(h):
            for x in range(w):
                r, g, b = palette[idx[y][x]]
                out += bytes((r, g, b, alpha_at(x, y, pattern)))
    elif mode == "p":
        for y in range(h):
            for x in range(w):
                out.append(idx[y][x])
    else:
        raise ValueError(mode)
    return bytes(out)


def build_image(mode: str, palette, idx, w: int, h: int, pattern: str) -> Image.Image:
    data = build_mode_bytes(mode, palette, idx, w, h, pattern)
    if mode == "l":
        return Image.frombytes("L", (w, h), data)
    if mode == "la":
        return Image.frombytes("LA", (w, h), data)
    if mode == "rgb":
        return Image.frombytes("RGB", (w, h), data)
    if mode == "rgba":
        return Image.frombytes("RGBA", (w, h), data)
    if mode == "p":
        im = Image.frombytes("P", (w, h), data)
        flat_palette = bytearray()
        for (r, g, b) in palette:
            flat_palette += bytes((r, g, b))
        im.putpalette(bytes(flat_palette), rawmode="RGB")
        return im
    raise ValueError(mode)


# ---------------------------------------------------------------------------
# Per-base-image file emission
# ---------------------------------------------------------------------------

generated_files: list[str] = []


def _write(path: Path, content: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(content)
    generated_files.append(str(path.relative_to(GOLDEN)))


def emit_base_image(name: str, im: Image.Image, mode: str) -> None:
    """Write `<name>.praw` (ground truth) plus every natural encoding of
    `im` for its mode: PNG always; BMP for l/rgb/p; PGM for l; PPM for rgb;
    GIF (+ a tRNS-transparency PNG variant) for p.

    BMP is *not* generated for `rgba`: Pillow's own 32bpp BMP writer always
    emits a plain 40-byte `BITMAPINFOHEADER` with no alpha bitmask
    (`PIL.BmpImagePlugin.SAVE["RGBA"]` writes `BGRA` pixel bytes but never
    the `BITMAPV4HEADER`/`BITMAPV5HEADER` needed to *declare* the 4th byte
    as alpha), so Pillow's own reader — and any spec-conformant BMP reader
    — opens it back as plain `RGB`, silently discarding alpha. Verified
    empirically: `Image.open(rgba_bmp_bytes).mode == "RGB"`. An "exact
    pixel" oracle fixture would therefore be comparing against data Pillow
    itself cannot round-trip, so it's skipped rather than encoding a
    misleading exactness claim."""
    m, w, h, data, palette = praw.image_to_praw_args(im)
    praw.write_praw(GOLDEN / f"{name}.praw", m, w, h, data, palette)
    generated_files.append(f"{name}.praw")

    buf = io.BytesIO()
    im.save(buf, "PNG")
    _write(GOLDEN / f"{name}.png", buf.getvalue())

    if mode in ("l", "rgb", "p"):
        buf = io.BytesIO()
        im.save(buf, "BMP")
        _write(GOLDEN / f"{name}.bmp", buf.getvalue())

    if mode == "l":
        buf = io.BytesIO()
        im.save(buf, "PPM")  # Pillow writes P5 (pgm) for L automatically
        _write(GOLDEN / f"{name}.pgm", buf.getvalue())

    if mode == "rgb":
        buf = io.BytesIO()
        im.save(buf, "PPM")
        _write(GOLDEN / f"{name}.ppm", buf.getvalue())

    if mode == "p":
        buf = io.BytesIO()
        im.save(buf, "GIF")
        _write(GOLDEN / f"{name}.gif", buf.getvalue())


def emit_p_transparency(name: str, palette, idx, w: int, h: int, pattern: str) -> None:
    """A second P-mode variant of the same index grid with a full per-index
    alpha table (tRNS), as its own named fixture (own .praw truth + .png)."""
    im = build_image("p", palette, idx, w, h, pattern)
    n = im.getpalette()
    n = len(n) // 3 if n else 0
    alphas = bytes((i * 53 + 29) % 256 for i in range(n))
    im.info["transparency"] = alphas

    tname = f"{name}_transparency"
    m, w2, h2, data, pal = praw.image_to_praw_args(im)
    praw.write_praw(GOLDEN / f"{tname}.praw", m, w2, h2, data, pal)
    generated_files.append(f"{tname}.praw")

    buf = io.BytesIO()
    im.save(buf, "PNG")
    _write(GOLDEN / f"{tname}.png", buf.getvalue())


def gen_pattern_matrix() -> tuple[Image.Image, int, int] | None:
    """Generate every (pattern, mode, size) fixture. Returns
    `(image, width, height)` for `PRINTED_PIXELS_OF`, needed for
    `Tests/RoundTripTests.lean`'s hardcoded assertions."""
    printed = None
    # 1x1 is only meaningful for `flat` (every other pattern degenerates to
    # a single arbitrary pixel indistinguishable from `flat` at this size).
    for pattern, fn in PATTERNS.items():
        seed = PATTERN_SEEDS[pattern]
        rng = random.Random(seed)
        sizes = SIZES + ([TINY_SIZE] if pattern == "flat" else [])
        for (w, h) in sizes:
            palette, idx = fn(rng, w, h)
            for mode in MODES:
                name = f"{pattern}_{mode}_{w}x{h}"
                im = build_image(mode, palette, idx, w, h, pattern)
                emit_base_image(name, im, mode)
                if mode == "p":
                    emit_p_transparency(name, palette, idx, w, h, pattern)
                if name == PRINTED_PIXELS_OF:
                    printed = (im, w, h)
    return printed


def gen_photo_jpeg() -> None:
    """One RGB "photo-ish" pattern (smooth gradient + noise), encoded as
    JPEG at three quality levels, plus its RGB source-of-truth .praw for
    PSNR comparison (JPEG is lossy, so crosscheck compares by PSNR, not
    exact bytes).

    Size 64×64 and noise amplitude ±2 are deliberately tuned (not
    arbitrary): JPEG's 8×8-block DCT quantization at quality 10 is harsh
    enough that a *tiny* image (the pattern matrix's usual 33×17) or
    stronger noise (±20) pushes even quality-10 PSNR below the crosscheck
    threshold of 30 dB — verified empirically across several sizes/
    amplitudes. 64×64 + ±2 clears 30 dB at q10 with a comfortable margin
    while still exercising all three quality levels meaningfully
    (q10≈30.6 dB, q75≈41.2 dB, q95≈43.8 dB against this exact seed)."""
    rng = random.Random(PHOTO_SEED)
    w, h = 64, 64
    noise_amp = 2

    def clip(v: int) -> int:
        return 0 if v < 0 else 255 if v > 255 else v

    data = bytearray()
    for y in range(h):
        for x in range(w):
            r = clip(x * 255 // (w - 1) + rng.randint(-noise_amp, noise_amp))
            g = clip(y * 255 // (h - 1) + rng.randint(-noise_amp, noise_amp))
            b = clip((x + y) * 255 // (w + h - 2) + rng.randint(-noise_amp, noise_amp))
            data += bytes((r, g, b))
    im = Image.frombytes("RGB", (w, h), bytes(data))

    name = f"photo_rgb_{w}x{h}"
    m, ww, hh, praw_data, _ = praw.image_to_praw_args(im)
    praw.write_praw(GOLDEN / f"{name}.praw", m, ww, hh, praw_data, None)
    generated_files.append(f"{name}.praw")

    for q in (10, 75, 95):
        buf = io.BytesIO()
        im.save(buf, "JPEG", quality=q)
        _write(GOLDEN / f"{name}_q{q}.jpg", buf.getvalue())


def gen_animated_gif() -> None:
    """One 3-frame animated GIF made of a checker pattern shifted each
    frame. No matching .praw truth (crosscheck.py skips files with none) —
    this fixture exists to exercise PILean's GIF *multi-frame* handling,
    not the single-frame pixel oracle."""
    rng = random.Random(ANIM_SEED)
    w, h = 16, 16
    c0 = (rng.randrange(256), rng.randrange(256), rng.randrange(256))
    c1 = (rng.randrange(256), rng.randrange(256), rng.randrange(256))
    frames = []
    for shift in range(3):
        data = bytearray()
        for y in range(h):
            for x in range(w):
                data.append((((x + shift * 3) // 8) + (y // 8)) % 2)
        im = Image.frombytes("P", (w, h), bytes(data))
        im.putpalette(bytes((c0[0], c0[1], c0[2], c1[0], c1[1], c1[2])), rawmode="RGB")
        frames.append(im)
    buf = io.BytesIO()
    frames[0].save(buf, "GIF", save_all=True, append_images=frames[1:], loop=0, duration=100)
    _write(GOLDEN / "checker_anim.gif", buf.getvalue())


# ---------------------------------------------------------------------------
# zlib corpus
# ---------------------------------------------------------------------------

TEXT_PARAGRAPH = (
    "The quick brown fox jumps over the lazy dog while the zlib deflate "
    "window slides across a stream of repeated English prose, testing "
    "match-finding at every offset it can reach. "
)


def zlib_corpus_data() -> dict[str, bytes]:
    data = {}
    data["empty"] = b""
    data["one"] = random.Random(ZLIB_SEEDS["one"]).randbytes(1)
    data["zeros"] = b"\x00" * 4096
    data["random4k"] = random.Random(ZLIB_SEEDS["random4k"]).randbytes(4096)
    text = (TEXT_PARAGRAPH * (20480 // len(TEXT_PARAGRAPH) + 1))[:20480]
    data["text"] = text.encode("ascii")
    data["b65535"] = random.Random(ZLIB_SEEDS["b65535"]).randbytes(65535)
    data["b65536"] = random.Random(ZLIB_SEEDS["b65536"]).randbytes(65536)
    # Spec suggested 200 KB; trimmed to 100 KB to keep testdata/golden under
    # the ~4 MB budget (random data is incompressible, so 10 zlib levels +
    # raw9 + bin each cost ~the full size — see MANIFEST.md).
    data["random100k"] = random.Random(ZLIB_SEEDS["random100k"]).randbytes(100_000)
    return data


def gen_zlib_corpus() -> None:
    for cls, raw in zlib_corpus_data().items():
        _write(ZLIB_DIR / f"{cls}.bin", raw)
        for level in range(10):
            _write(ZLIB_DIR / f"{cls}.z{level}", zlib.compress(raw, level))
        co = zlib.compressobj(9, zlib.DEFLATED, -15)
        raw9 = co.compress(raw) + co.flush()
        _write(ZLIB_DIR / f"{cls}.raw9", raw9)


