def write_manifest(printed_pixels: list[tuple[int, int, tuple]]) -> None:
    import PIL

    lines = []
    lines.append("# testdata/golden — provenance and regeneration")
    lines.append("")
    lines.append("Generated by `testdata/py/gen_golden.py`. Goldens are checked in and never")
    lines.append("regenerated in CI — only by re-running this script by hand and reviewing")
    lines.append("the diff.")
    lines.append("")
    lines.append("## Versions")
    lines.append("")
    lines.append(f"- Python: `{sys.version.split()[0]}`")
    lines.append(f"- Pillow: `{PIL.__version__}` (pin: 11.3.0)")
    lines.append(f"- zlib (Python's `zlib` module): `{zlib.ZLIB_VERSION}`")
    lines.append("")
    lines.append("## Regeneration")
    lines.append("")
    lines.append("```sh")
    lines.append("python3 testdata/py/gen_golden.py       # rewrites testdata/golden/** and")
    lines.append("                                      # testdata/corpus/pngsuite-truth/**")
    lines.append("python3 testdata/py/crosscheck.py        # verify PILean's own output later")
    lines.append("```")
    lines.append("")
    lines.append("## Pattern matrix seeds")
    lines.append("")
    lines.append("One `random.Random(seed)` per pattern name, threaded through both sizes")
    lines.append("(16×16 then 33×17, in that order; `flat` additionally does 1×1 last) in")
    lines.append("a fixed loop order — reseeded only at the start of each pattern, per the")
    lines.append("work package spec (\"random.Random(seed) per pattern\").")
    lines.append("")
    lines.append("| pattern | seed |")
    lines.append("|---|---|")
    for k, v in PATTERN_SEEDS.items():
        lines.append(f"| {k} | {v} |")
    lines.append(f"| photo (JPEG source) | {PHOTO_SEED} |")
    lines.append(f"| checker_anim.gif | {ANIM_SEED} |")
    lines.append("")
    lines.append("`hgradient`/`vgradient` are deterministic ramps needing no randomness "
                  "(the `rng` parameter is accepted but unused, to keep a uniform pattern "
                  "function signature).")
    lines.append("")
    lines.append("Sizes: 16×16 and 33×17 for every pattern × mode (l, la, rgb, rgba, p); "
                  "1×1 only for `flat` (the only pattern that isn't visually degenerate at "
                  "a single pixel — checker/gradient/noise/fewcolors would just look like "
                  "`flat` there too, so those combinations are skipped).")
    lines.append("")
    lines.append("P-mode images additionally get a `<name>_transparency.{praw,png}` "
                  "variant: same index grid, palette alpha `(i*53+29) % 256` per index "
                  "`i`, written as a PNG tRNS chunk.")
    lines.append("")
    lines.append("`.bmp` is generated for `l`/`rgb`/`p` only, **not** `rgba`: Pillow's own "
                  "32bpp BMP writer never declares an alpha bitmask, so Pillow's own reader "
                  "(and any conformant BMP reader) opens the result back as plain `RGB`, "
                  "silently dropping alpha — verified empirically. An RGBA BMP fixture "
                  "would be an \"exact\" oracle for data Pillow itself cannot round-trip, "
                  "so it's skipped. `.gif`'s global color table must be a power-of-two "
                  "size, so Pillow zero-pads P-mode palettes on write; `crosscheck.py` "
                  "accordingly only requires the *first* `len(truth palette)` GIF palette "
                  "entries to match, not the padding.")
    lines.append("")
    lines.append("## JPEG photo pattern")
    lines.append("")
    lines.append(f"`photo_rgb_64x64` — smooth diagonal RGB gradient (`x`, `y`, `x+y` ramps) "
                  "plus `randint(-2, 2)` per-channel noise, seed "
                  f"{PHOTO_SEED}. Encoded at quality 10/75/95. JPEG is lossy — "
                  "`crosscheck.py` compares by PSNR (≥ 30 dB) against `photo_rgb_64x64.praw`, "
                  "not exact bytes. Size and noise amplitude are tuned so quality-10 clears "
                  "30 dB with margin — a tiny image or stronger noise pushes even "
                  "quality-10 JPEG below the threshold on pure block-quantization loss "
                  "alone (verified empirically; see the generator's docstring).")
    lines.append("")
    lines.append("## Animated GIF")
    lines.append("")
    lines.append(f"`checker_anim.gif` — 3 frames, an 8×8 checkerboard (seed {ANIM_SEED} for "
                  "its two colors) shifted 3px horizontally per frame. No `.praw` truth "
                  "(multi-frame; `crosscheck.py` skips files with no matching golden "
                  "with a warning) — exists to exercise multi-frame GIF decoding.")
    lines.append("")
    lines.append("## zlib corpus (`testdata/golden/zlib/`)")
    lines.append("")
    lines.append("Each data class `<class>` is written as `<class>.bin` (raw), "
                  "`<class>.z0` … `<class>.z9` (`zlib.compress(data, level)` for level "
                  "0–9), and `<class>.raw9` (`zlib.compressobj(9, zlib.DEFLATED, "
                  "wbits=-15)` — a raw, headerless deflate stream at level 9).")
    lines.append("")
    lines.append("| class | size | seed | notes |")
    lines.append("|---|---|---|---|")
    lines.append("| empty | 0 B | — | |")
    lines.append(f"| one | 1 B | {ZLIB_SEEDS['one']} | |")
    lines.append("| zeros | 4096 B | — | all `\\x00` |")
    lines.append(f"| random4k | 4096 B | {ZLIB_SEEDS['random4k']} | |")
    lines.append("| text | 20480 B | — | repeated English paragraph (see script) |")
    lines.append(f"| b65535 | 65535 B | {ZLIB_SEEDS['b65535']} | one byte short of the 64 KiB "
                  "DEFLATE stored-block boundary |")
    lines.append(f"| b65536 | 65536 B | {ZLIB_SEEDS['b65536']} | exactly the 64 KiB boundary |")
    lines.append(f"| random100k | 100000 B | {ZLIB_SEEDS['random100k']} | **trimmed from the "
                  "spec's suggested 200 KB** — random data is incompressible, so all 12 "
                  "variants (bin + 10 levels + raw9) cost ~the full size each; 200 KB would "
                  "have used ~2.4 MB alone. 100 KB keeps `testdata/golden` comfortably under "
                  "the ~4 MB budget. |")
    lines.append("")
    lines.append("## PngSuite corpus")
    lines.append("")
    lines.append("Vendored under `testdata/corpus/pngsuite/` (separate from the ~4 MB "
                  "`testdata/golden` budget — see `testdata/corpus/pngsuite/README.md` for "
                  "provenance, license, and the corrupt-file list). Pixel truth is "
                  "generated into `testdata/corpus/pngsuite-truth/*.praw` by "
                  "`testdata/py/pngsuite_truth.py` (invoked automatically by this script) — "
                  "see that script's module docstring for PILean's exact 16-bit-to-8-bit "
                  "normalization rules.")
    lines.append("")
    lines.append("- Source: `http://www.schaik.com/pngsuite2011/PngSuite-2017jul19.tgz`")
    lines.append("- Downloaded: 2026-07-11")
    lines.append("")
    lines.append("## Hardcoded pixel values for `Tests/RoundTripTests.lean`")
    lines.append("")
    lines.append(f"From `{PRINTED_PIXELS_OF}.praw` (also committed as the fixture itself):")
    lines.append("")
    lines.append("| (x, y) | RGB |")
    lines.append("|---|---|")
    for (x, y), rgb in printed_pixels:
        lines.append(f"| ({x}, {y}) | {rgb} |")
    lines.append("")
    lines.append("## Full file list")
    lines.append("")
    lines.append(f"{len(generated_files)} files generated by the most recent run of this "
                  "script (excluding this MANIFEST itself). Re-run "
                  "`python3 testdata/py/gen_golden.py` to regenerate; diff `git status` "
                  "afterward to confirm no unexpected changes.")
    lines.append("")

    (GOLDEN / "MANIFEST.md").write_text("\n".join(lines) + "\n")


def main() -> None:
    GOLDEN.mkdir(parents=True, exist_ok=True)
    ZLIB_DIR.mkdir(parents=True, exist_ok=True)

    printed_image = gen_pattern_matrix()
    gen_photo_jpeg()
    gen_animated_gif()
    gen_zlib_corpus()

    printed_pixels = []
    if printed_image is not None:
        im, w, h = printed_image
        for (x, y) in PRINTED_COORDS:
            if x < w and y < h:
                printed_pixels.append(((x, y), im.getpixel((x, y))))
    write_manifest(printed_pixels)

    corpus_dir = ROOT / "corpus" / "pngsuite"
    truth_dir = ROOT / "corpus" / "pngsuite-truth"
    if corpus_dir.exists() and any(corpus_dir.glob("*.png")):
        generated, skipped = pngsuite_truth.generate(corpus_dir, truth_dir)
        print(f"pngsuite_truth: wrote {generated} truth .praw files "
              f"({skipped} corrupt skipped)")
    else:
        print(f"pngsuite_truth: no vendored corpus at {corpus_dir}, skipping", file=sys.stderr)

    total_bytes = sum((GOLDEN / f).stat().st_size for f in generated_files)
    print(f"gen_golden: wrote {len(generated_files)} files under {GOLDEN} "
          f"({total_bytes / 1024:.1f} KiB)")
    print(f"\nHardcode these into Tests/RoundTripTests.lean "
          f"(fixture {PRINTED_PIXELS_OF}.praw):")
    for (x, y), rgb in printed_pixels:
        print(f"  ({x}, {y}) -> {rgb}")


if __name__ == "__main__":
    main()
